(function() {
    'use strict';

    class ERPsimAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'ERPsim: Process Integration Explorer';
            this.version = '1.1.0';

            this.MODULE_NAMES = ['', 'SD', 'MM', 'PP', 'FICO'];
            this.ROOTCAUSE_NAMES = ['', 'Master Data Error', 'Transaction Error', 'Configuration Error', 'Process Violation', 'Data Quality Issue'];
            this.ACTION_NAMES = ['', 'Update Master Data', 'Correct Transaction', 'Reconfigure System', 'Adjust Process Controls', 'Escalate to Management'];

            this.ROUNDS = [
                {
                    title: 'Sales Order Rejection',
                    icon: '🛑',
                    description: '<strong>Incident Report:</strong> A sales representative tries to create a sales order for customer C-4500 requesting 500 units of finished good FG-2000. The system rejects the order with error: <em>"Material FG-2000 not defined for sales organization 1000."</em><br><br>The material master record exists in the system and is visible in MM. Production has been manufacturing FG-2000 for months. The warehouse shows 800 units in stock.<br><br><strong>Your task:</strong> Identify which module contains the error, the root cause category, and the correct fix.',
                    dataFlow: '<span class="erpsim-flow-highlight">SD: Sales Order ✗</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">MM: Availability Check</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">PP: Production</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">FICO: Billing</span>',
                    correctModule: 1,
                    correctRootCause: 1,
                    correctAction: 1,
                    costImpact: 15000,
                    explanation: 'The material master lacked a Sales Org 1000 assignment in the SD view. Without this master data extension, SD cannot sell the material even though it physically exists. Fix: extend the material master to include the sales organization view.'
                },
                {
                    title: 'Bill of Materials Defect',
                    icon: '🔧',
                    description: '<strong>Incident Report:</strong> Quality control rejects an entire production batch of product FG-3000. The finished goods contain 3 kg of raw material RM-100 per unit instead of the required 5 kg. Production followed the system BOM exactly.<br><br>Investigation reveals the BOM was migrated from a legacy system 6 months ago and the quantity field was truncated during data conversion.<br><br><strong>Your task:</strong> Identify the affected module, root cause, and corrective action.',
                    dataFlow: '<span class="erpsim-flow-ok">SD: Sales Order ✓</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">MM: Material Issued</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-highlight">PP: BOM Error ✗</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">FICO: Cost Variance</span>',
                    correctModule: 3,
                    correctRootCause: 1,
                    correctAction: 1,
                    costImpact: 85000,
                    explanation: 'The BOM master data in PP contained an incorrect component quantity from a flawed data migration. Fix: correct the BOM quantity for RM-100 from 3 kg to 5 kg and implement a master data validation process for all migrated records.'
                },
                {
                    title: 'Phantom Inventory Crisis',
                    icon: '📦',
                    description: '<strong>Incident Report:</strong> Sales has promised delivery of 800 units to a key customer based on system-reported inventory of 1,000 units. When the warehouse attempts to pick the goods, they find only 200 units on the shelf.<br><br>The 800-unit discrepancy accumulated over several months. Goods receipts were posted in the system but physical goods were damaged and discarded without recording inventory adjustments.<br><br><strong>Your task:</strong> Diagnose the module, root cause, and corrective action.',
                    dataFlow: '<span class="erpsim-flow-ok">SD: Delivery Created</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-highlight">MM: Inventory Mismatch ✗</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">PP: Not Affected</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">FICO: Wrong Valuation</span>',
                    correctModule: 2,
                    correctRootCause: 5,
                    correctAction: 2,
                    costImpact: 120000,
                    explanation: 'Warehouse staff discarded damaged goods without posting inventory adjustments in MM, creating a data quality gap between physical and system inventory. Fix: perform a physical inventory count, post correction entries, and implement mandatory goods movement postings for all warehouse disposals.'
                },
                {
                    title: 'Lead Time Catastrophe',
                    icon: '⏰',
                    description: '<strong>Incident Report:</strong> Production has halted on line 3. MRP generated purchase orders for critical component RM-500 with a 5-day lead time, but the actual supplier lead time is 15 days. Materials will arrive 10 days late, stopping production and delaying customer deliveries.<br><br>The material master shows a planned delivery time of 5 days. This value was set during initial system configuration two years ago and never updated when the company switched to an overseas supplier.<br><br><strong>Estimated damage:</strong> €200,000 in production downtime and late delivery penalties.',
                    dataFlow: '<span class="erpsim-flow-ok">SD: Customer Orders Waiting</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-highlight">MM: MRP Lead Time = 5d (Actual = 15d) ✗</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">PP: Line Stopped</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">FICO: Penalty Accrual</span>',
                    correctModule: 2,
                    correctRootCause: 1,
                    correctAction: 1,
                    costImpact: 200000,
                    explanation: 'The material master planned delivery time in MM was outdated (5 days vs. actual 15 days). MRP used this incorrect data to schedule procurement, resulting in late material arrivals. Fix: update the planned delivery time in the material master and implement periodic master data review for all sourcing-critical materials.'
                },
                {
                    title: 'Invoice Price Dispute',
                    icon: '💰',
                    description: '<strong>Incident Report:</strong> Customer C-7200 has disputed an invoice. The sales order confirmed a unit price of €38, but the invoice shows €45 per unit. The customer is threatening to cancel a €2M annual contract.<br><br>Investigation shows the sales order was created with a customer-specific pricing condition (K004) at €38. However, the billing document picked up a different condition record (PR00 base price) at €45 because the customer-specific condition had expired between order creation and billing.<br><br><strong>Your task:</strong> Diagnose and recommend the fix.',
                    dataFlow: '<span class="erpsim-flow-highlight">SD: Pricing Condition Expired ✗</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">MM: Not Affected</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">PP: Not Affected</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">FICO: Revenue Overstated</span>',
                    correctModule: 1,
                    correctRootCause: 3,
                    correctAction: 3,
                    costImpact: 55000,
                    explanation: 'The SD pricing condition record (K004) had a validity period that expired before billing occurred. The system fell back to the base price (PR00). Fix: reconfigure the pricing procedure to flag condition expiry warnings, extend the customer-specific condition validity, and issue a credit memo for the difference.'
                },
                {
                    title: 'Blocked Delivery',
                    icon: '🚫',
                    description: '<strong>Incident Report:</strong> 2,000 units of product FG-1000 are packed and ready in the warehouse, but the system blocks the delivery. The block reason: "Credit limit exceeded for customer C-3100."<br><br>Customer C-3100 has a credit limit of €500,000. Their current receivables balance is €480,000 and this delivery is worth €75,000. The credit management configuration requires automatic blocking when the limit is exceeded, but no alert was sent to the credit team when the customer approached 90% of their limit.<br><br><strong>Your task:</strong> Identify the issue and recommend a fix.',
                    dataFlow: '<span class="erpsim-flow-ok">SD: Delivery Created</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">MM: Goods Picked</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">PP: Not Affected</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-highlight">FICO: Credit Block ✗</span>',
                    correctModule: 4,
                    correctRootCause: 3,
                    correctAction: 3,
                    costImpact: 75000,
                    explanation: 'The FICO credit management configuration lacked proactive alerting thresholds. While the credit block worked correctly, the absence of early warning notifications (at 80-90% utilization) meant no one could take preemptive action. Fix: reconfigure credit management to include automatic alerts at 80% and 90% thresholds, and establish a credit review workflow.'
                },
                {
                    title: 'Production Cost Variance',
                    icon: '📉',
                    description: '<strong>Incident Report:</strong> Month-end closing reveals a massive production variance on product line FG-5000. Standard cost per unit is €12, but actual cost is €22 — an 83% overrun. Total variance for the month: €150,000.<br><br>Analysis shows the cost center allocation for overhead in the routing was set to cost center CC-4400 (administrative) instead of CC-2200 (production). The administrative overhead rate is €18/hour versus the production rate of €8/hour.<br><br><strong>Your task:</strong> Identify the source and fix.',
                    dataFlow: '<span class="erpsim-flow-ok">SD: Revenue OK</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">MM: Material Cost OK</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">PP: Routing References Wrong CC</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-highlight">FICO: Cost Center Error ✗</span>',
                    correctModule: 4,
                    correctRootCause: 1,
                    correctAction: 1,
                    costImpact: 150000,
                    explanation: 'The production routing referenced the wrong cost center (CC-4400 administrative instead of CC-2200 production) in the FICO master data, causing overhead to be calculated at the wrong rate. Fix: update the cost center assignment in the routing master data and rerun the cost estimate for FG-5000. Implement cross-module master data validation for cost-relevant fields.'
                },
                {
                    title: 'Vendor Payment Terms Error',
                    icon: '💸',
                    description: '<strong>Incident Report:</strong> The treasury department discovers a cash flow crisis. Over the past 3 months, the system has been paying vendor V-9000 on Net 10 terms instead of the agreed Net 60 terms. This vendor supplies €1.2M worth of materials monthly.<br><br>Investigation reveals the vendor master record was updated by a junior clerk who accidentally changed the payment terms from "Z060" (Net 60) to "Z010" (Net 10) while updating the bank details. No approval workflow was triggered for this change.<br><br><strong>Estimated cash flow impact:</strong> €350,000 in premature outflows over 3 months.',
                    dataFlow: '<span class="erpsim-flow-ok">SD: Not Affected</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-highlight">MM: Vendor Master Error ✗</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">PP: Not Affected</span> <span class="erpsim-flow-arrow">→</span> <span class="erpsim-flow-ok">FICO: Early Payment Outflows</span>',
                    correctModule: 2,
                    correctRootCause: 1,
                    correctAction: 1,
                    costImpact: 350000,
                    explanation: 'The vendor master record in MM had payment terms changed without proper approval. The lack of a change management workflow for sensitive master data fields allowed an unauthorized modification to go undetected for months. Fix: correct the payment terms in the vendor master, implement dual-approval workflow for sensitive vendor master fields, and negotiate recovery of the cash flow impact with the vendor.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    totalScore: 0,
                    maxPossibleScore: 0,
                    costAvoided: 0,
                    correctModules: 0,
                    correctRootCauses: 0,
                    correctActions: 0,
                    totalAttempts: 0,
                    modulesCorrectSet: [],
                    scoreHistory: [],
                    accuracyHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    moduleChoice: 0,
                    rootCauseChoice: 0,
                    actionChoice: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var moduleSelect = document.getElementById('moduleSelect');
            if (moduleSelect) decisions.moduleChoice = parseInt(moduleSelect.value);

            var rootCauseSelect = document.getElementById('rootCauseSelect');
            if (rootCauseSelect) decisions.rootCauseChoice = parseInt(rootCauseSelect.value);

            var actionSelect = document.getElementById('actionSelect');
            if (actionSelect) decisions.actionChoice = parseInt(actionSelect.value);

            if (!decisions.moduleChoice || decisions.moduleChoice < 1 || decisions.moduleChoice > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_module_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.rootCauseChoice || decisions.rootCauseChoice < 1 || decisions.rootCauseChoice > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_rootcause_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.actionChoice || decisions.actionChoice < 1 || decisions.actionChoice > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_action_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var moduleCorrect = (d.moduleChoice === round.correctModule) ? 1 : 0;
            var rootCauseCorrect = (d.rootCauseChoice === round.correctRootCause) ? 1 : 0;
            var actionCorrect = (d.actionChoice === round.correctAction) ? 1 : 0;

            var modulePoints = moduleCorrect * 15;
            var rootCausePoints = rootCauseCorrect * 20;
            var actionPoints = actionCorrect * 15;
            var periodScore = modulePoints + rootCausePoints + actionPoints;
            var maxPeriodScore = 50;

            var costSaved = 0;
            if (periodScore >= 40) {
                costSaved = round.costImpact;
            } else if (periodScore >= 25) {
                costSaved = Math.round(round.costImpact * 0.5);
            }

            state.domainState.totalScore += periodScore;
            state.domainState.maxPossibleScore += maxPeriodScore;
            state.domainState.costAvoided += costSaved;
            state.domainState.correctModules += moduleCorrect;
            state.domainState.correctRootCauses += rootCauseCorrect;
            state.domainState.correctActions += actionCorrect;
            state.domainState.totalAttempts += 1;

            if (moduleCorrect && state.domainState.modulesCorrectSet.indexOf(d.moduleChoice) === -1) {
                state.domainState.modulesCorrectSet.push(d.moduleChoice);
            }

            var accuracyPct = Math.round((state.domainState.totalScore / state.domainState.maxPossibleScore) * 100);
            state.domainState.scoreHistory.push(state.domainState.totalScore);
            state.domainState.accuracyHistory.push(accuracyPct);

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                feedbackPanel.style.display = 'block';
                feedbackPanel.className = 'erpsim-sim-feedback';
                var fb = '';
                if (periodScore >= 40) {
                    feedbackPanel.classList.add('erpsim-feedback-good');
                    fb += '<strong>✅ Excellent diagnosis! (' + periodScore + '/' + maxPeriodScore + ' points)</strong><br><br>';
                } else if (periodScore >= 20) {
                    feedbackPanel.classList.add('erpsim-feedback-partial');
                    fb += '<strong>⚠️ Partial diagnosis (' + periodScore + '/' + maxPeriodScore + ' points)</strong><br><br>';
                } else {
                    feedbackPanel.classList.add('erpsim-feedback-wrong');
                    fb += '<strong>❌ Incorrect diagnosis (' + periodScore + '/' + maxPeriodScore + ' points)</strong><br><br>';
                }
                fb += '<strong>Module:</strong> ' + (moduleCorrect ? '✅' : '❌') + ' You selected ' + this.MODULE_NAMES[d.moduleChoice] + (moduleCorrect ? ' (Correct!)' : ' — Correct answer: ' + this.MODULE_NAMES[round.correctModule]) + '<br>';
                fb += '<strong>Root Cause:</strong> ' + (rootCauseCorrect ? '✅' : '❌') + ' You selected ' + this.ROOTCAUSE_NAMES[d.rootCauseChoice] + (rootCauseCorrect ? ' (Correct!)' : ' — Correct answer: ' + this.ROOTCAUSE_NAMES[round.correctRootCause]) + '<br>';
                fb += '<strong>Action:</strong> ' + (actionCorrect ? '✅' : '❌') + ' You selected ' + this.ACTION_NAMES[d.actionChoice] + (actionCorrect ? ' (Correct!)' : ' — Correct answer: ' + this.ACTION_NAMES[round.correctAction]) + '<br><br>';
                fb += '<strong>Explanation:</strong> ' + round.explanation;
                if (costSaved > 0) {
                    fb += '<br><br>💶 <strong>Cost avoided:</strong> €' + costSaved.toLocaleString();
                }
                feedbackText.innerHTML = fb;
            }

            var self = this;
            var gradedPeriod = state.currentPeriod;
            setTimeout(function() {
                if (gradedPeriod < self.ROUNDS.length) {
                    self._updateBriefing({ currentPeriod: gradedPeriod + 1 });
                }
                var moduleSelect = document.getElementById('moduleSelect');
                var rootCauseSelect = document.getElementById('rootCauseSelect');
                var actionSelect = document.getElementById('actionSelect');
                if (moduleSelect) moduleSelect.value = '0';
                if (rootCauseSelect) rootCauseSelect.value = '0';
                if (actionSelect) actionSelect.value = '0';
            }, 500);

            return {
                period: state.currentPeriod,
                scenarioTitle: round.title,
                moduleChoice: this.MODULE_NAMES[d.moduleChoice],
                rootCauseChoice: this.ROOTCAUSE_NAMES[d.rootCauseChoice],
                actionChoice: this.ACTION_NAMES[d.actionChoice],
                moduleCorrect: moduleCorrect,
                rootCauseCorrect: rootCauseCorrect,
                actionCorrect: actionCorrect,
                periodScore: periodScore,
                costSaved: costSaved,
                totalScore: state.domainState.totalScore,
                accuracyPct: accuracyPct
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore',
                function(v) { return v + ' pts'; });
