        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0;
            var totalCostSaved = 0;
            var perfectRounds = 0;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results;
                if (r) {
                    totalScore += (r.periodScore || 0);
                    totalCostSaved += (r.costSaved || 0);
                    if (r.periodScore === 50) perfectRounds++;
                }
            }
            var avgScore = Math.round(totalScore / history.length);
            var accuracyPct = Math.round((totalScore / (history.length * 50)) * 100);

            var t = function(k) { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; };
            var performance = t('tier_beginner');
            if (totalScore >= 350 && perfectRounds >= 5) performance = t('tier_expert');
            else if (totalScore >= 250) performance = t('tier_proficient');
            else if (totalScore >= 150) performance = t('tier_developing');

            var insights = [];
            if (accuracyPct >= 80) {
                insights.push(t('insight_high'));
            } else if (accuracyPct >= 60) {
                insights.push(t('insight_mid'));
            } else {
                insights.push(t('insight_low'));
            }
            if (perfectRounds >= 3) {
                insights.push(t('insight_perfect_rounds').replace('{n}', perfectRounds));
            }

            return {
                totalScore: totalScore,
                maxScore: history.length * 50,
                avgScore: avgScore,
                accuracyPct: accuracyPct,
                totalCostSaved: totalCostSaved,
                perfectRounds: perfectRounds,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.periodScore === 50) {
                return window.mySimulation.t('hint_perfect');
            }
            if (results.periodScore >= 25) {
                return window.mySimulation.t('hint_partial');
            }
            return window.mySimulation.t('hint_wrong');
        }

